/**
 * The handful of Python `str` behaviours the ekko-pnc port depends on, matched exactly.
 *
 * Python works on code points, JavaScript strings on UTF-16 units, so everything here takes
 * one code point (a string of length 1 or 2). The character classes come from the engine's
 * Unicode property escapes, which agree with Python's on every code point Python's Unicode
 * version knows; the two places JavaScript differs by design (whitespace and titlecase) come
 * from tables generated by Python itself (scripts/generate-titlecase-table.py).
 */

import { PYTHON_WHITESPACE, TITLECASE_EXCEPTIONS } from './python-text-tables'

const WHITESPACE_RUN = new RegExp(
  `[${Array.from(PYTHON_WHITESPACE, (character) => `\\u{${character.codePointAt(0)!.toString(16)}}`).join('')}]+`,
  'u'
)

/** Python `text.split()`: split on runs of Python whitespace, dropping empty ends. */
export function pythonSplit(text: string): string[] {
  return text.split(WHITESPACE_RUN).filter((word) => word !== '')
}

/**
 * Python `c.isupper() or c.istitle()` for one code point: it has the Uppercase property
 * (which includes `Ⓐ` and Roman numerals, not only Lu) or is a titlecase letter (Lt).
 */
export function isUpperOrTitle(character: string): boolean {
  return /^[\p{Uppercase}\p{Lt}]$/u.test(character)
}

/** Python `c.isalpha()` for one code point: categories Lu, Ll, Lt, Lm and Lo. */
export function isAlpha(character: string): boolean {
  return /^\p{L}$/u.test(character)
}

/** Python `c.title()` for one code point, with its special mappings (`ß` -> `Ss`, `ǆ` -> `ǅ`). */
export function title(character: string): string {
  return TITLECASE_EXCEPTIONS.get(character) ?? character.toUpperCase()
}
